"""Use only the disposable profile generated by windows-dialog.ps1; never emit a token."""
import http.server
import json
import os
from pathlib import Path
import re
import secrets
import subprocess
import sys
import threading
import time
import tomllib

home = Path(os.environ["CODEX_HOME"])
assert os.environ.get("GITHUB_ACTIONS") == "true" and re.fullmatch("sworncard-test-[0-9a-f]{32}", home.parent.name)
config = home / "config.toml"
raw = config.read_text(encoding="utf-8")
snapshot = tomllib.loads(raw)
assert snapshot["plugins"]["sworncard-connect@sworncard-connect"]["mcp_servers"]["sworncard"]["enabled"] is False
servers = snapshot["mcp_servers"]
name, entry = next((n, s) for n, s in servers.items() if n.startswith("sworncard_pc_"))
assert entry["url"] == "https://connect.sworncard.ru/mcp"
header = entry["http_headers"]["Authorization"]
calls = []

class Fixture(http.server.BaseHTTPRequestHandler):
    def log_message(self, *unused):
        pass

    def do_GET(self):
        self.send_error(405)

    def do_POST(self):
        if not secrets.compare_digest(self.headers.get("Authorization", ""), header):
            self.send_error(401)
            return
        event = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        method = event["method"]
        calls.append(method)
        if "id" not in event:
            self.send_response(202)
            self.end_headers()
            return
        if method == "initialize":
            result = {"protocolVersion": event["params"]["protocolVersion"], "capabilities": {"tools": {}},
                      "serverInfo": {"name": "synthetic", "version": "1"}}
        elif method == "tools/list":
            result = {"tools": [{"name": "list_connections", "description": "Synthetic catalogue",
                                 "inputSchema": {"type": "object", "properties": {}}}]}
        elif method == "tools/call" and event["params"]["name"] == "list_connections":
            result = {"content": [{"type": "text", "text": "Synthetic Windows catalogue"}]}
        else:
            result = {}
        body = json.dumps({"jsonrpc": "2.0", "id": event["id"], "result": result}).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

def rpc(proc, i, method, params):
    proc.stdin.write(json.dumps({"id": i, "method": method, "params": params}) + "\n")
    proc.stdin.flush()
    for line in proc.stdout:
        event = json.loads(line)
        if event.get("id") == i:
            if "result" not in event:
                raise RuntimeError(method + " failed")
            return event["result"]
    raise RuntimeError("Codex disconnected")

with http.server.ThreadingHTTPServer(("127.0.0.1", 0), Fixture) as fixture:
    threading.Thread(target=fixture.serve_forever, daemon=True).start()
    try:
        # Only substitute the endpoint in this disposable profile after checking the shipped pin.
        config.write_text(raw.replace('https://connect.sworncard.ru/mcp', f'http://127.0.0.1:{fixture.server_port}/mcp'), encoding='utf-8')
        p = subprocess.Popen([sys.argv[1], "app-server", "--listen", "stdio://"], cwd=home.parent,
                             stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, encoding="utf-8")
        try:
            rpc(p, 1, "initialize", {"clientInfo": {"name": "acceptance", "version": "1"}, "capabilities": {"experimentalApi": True}})
            p.stdin.write('{"method":"initialized"}\n'); p.stdin.flush()
            t = rpc(p, 2, "thread/start", {"cwd": str(home.parent), "ephemeral": True})
            result = rpc(p, 3, "mcpServer/tool/call", {"threadId": t["thread"]["id"], "server": name,
                                                      "tool": "list_connections", "arguments": {}})
            assert "Synthetic Windows catalogue" in json.dumps(result) and "tools/call" in calls
            print("Passed: restarted Windows Desktop engine authenticated and returned the synthetic catalogue.")
        finally:
            p.kill(); p.wait(timeout=10)
    finally:
        config.write_text(raw, encoding="utf-8")
        fixture.shutdown()

# Search disposable client state for the synthetic secret without logging any file contents.
needle = header.split(" ", 1)[1].encode()
def check_file(file):
    # Desktop background tasks can briefly lock or remove their own temporary checkout files.
    for attempt in range(10):
        try:
            if not file.is_file():
                return
            with file.open("rb") as stream:
                overlap = b""
                while chunk := stream.read(65536):
                    data = overlap + chunk
                    assert needle not in data, "Synthetic credential appeared outside the personal config"
                    overlap = data[-(len(needle) - 1):]
            return
        except FileNotFoundError:
            return
        except PermissionError:
            if attempt == 9:
                raise
            time.sleep(0.5)

for file in home.rglob("*"):
    if file != config:
        check_file(file)
print("Passed: synthetic PAT remained in the personal configuration.")
